import{_ as a,C as r,o as i,c as d,j as t,a as o,E as n,a2 as h}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"Sync","description":"","frontmatter":{"title":"Sync"},"headers":[],"relativePath":"en/guide/sync.md","filePath":"en/guide/sync.md"}'),l={name:"en/guide/sync.md"};function c(m,e,g,u,p,y){const s=r("Capture");return i(),d("div",null,[e[0]||(e[0]=t("h1",{id:"sync",tabindex:"-1"},[o("Sync "),t("a",{class:"header-anchor",href:"#sync","aria-label":'Permalink to "Sync"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Your memory is an ordinary git repository. Kessho syncs it, with the git installed on your computer, to the remote you choose, and never forces anything. An indicator also tells you when the memory has just changed.",-1)),n(s,{name:"synchro",alt:"Memory synchronization: files changed since the last commit and a commit message being typed."}),e[2]||(e[2]=h('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Syncing is driven from two places: the status bar, for one click, and <a href="/en/guide/settings.html">Settings</a> &gt; <strong>Sync</strong>, for the detail.</p><ul><li><strong>In the status bar</strong>, at the bottom of the window: <ul><li>the <strong>Sync the memory</strong> button, far left (tooltip: &quot;Sync: commit, pull, push&quot;);</li><li>the <strong>git</strong> field, which tells you where the repository stands: <strong>up to date</strong>, <strong>N to push</strong>, <strong>N to pull</strong>, <strong>N uncommitted</strong>, <strong>conflict</strong> or <strong>operation in progress</strong>. The tooltip gives the full state line.</li></ul></li><li><strong>In Settings &gt; Sync</strong>: <ul><li><strong>The state line</strong>: the branch and what it tracks, then how far behind and ahead it is, for example &quot;main → origin/main · 2 to push · 0 to pull · remote checked 10:30&quot;. The time is when the remote was last checked.</li><li><strong>The three actions</strong>: <strong>Sync</strong>, <strong>Pull</strong>, <strong>Push</strong>.</li><li><strong>Changes</strong>: the number of modified, deleted and untracked files (&quot;3 modified · 0 deleted · 1 untracked&quot;), the <strong>Show the list</strong> disclosure, the <strong>Commit message</strong> field and the <strong>Commit the changes</strong> button.</li><li><strong>Remote</strong>: the address of the remote repository, and the <strong>Remote URL (https or ssh)</strong> field.</li><li><strong>Automation</strong>: the &quot;Agents commit and sync automatically&quot; checkbox.</li><li><strong>Commit messages</strong>: one line per origin (<strong>One click</strong>, <strong>Automation</strong>, <strong>Manual</strong>, <strong>AI agent</strong>) with the chosen template and its <strong>Preview</strong>, then <strong>My templates</strong> and the <strong>New template</strong> button.</li><li><strong>Warnings</strong>, when there is something to say.</li></ul></li><li><strong>The freshness indicator</strong>, top right, next to your avatar: a dot that lights up when the memory changes.</li></ul><p>If the memory is not a repository yet, the section says: &quot;This memory is not a git repository. Initialising it creates no commit and connects no remote.&quot; If git is not installed, it shows &quot;git not found&quot; with the command to install it. The rest of Kessho works without git.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="sync-in-one-click" tabindex="-1">Sync in one click <a class="header-anchor" href="#sync-in-one-click" aria-label="Permalink to &quot;Sync in one click&quot;">​</a></h3><p>Click <strong>Sync the memory</strong> in the status bar. Kessho does three things, in this order:</p><ol><li>it commits what changed, under the message composed by the <strong>One click</strong> origin&#39;s template, by default &quot;vault backup: YYYY-MM-DD HH:mm:ss&quot; (nothing is committed if there is nothing new);</li><li>it pulls what is new on the remote;</li><li>it pushes your commits.</li></ol><p>Nothing is stashed and nothing is forced. When it finishes, the <strong>git</strong> field updates; a screen reader hears &quot;Memory synced.&quot;.</p><p>If something blocks it, the bar shows &quot;failed:&quot; followed by one word (<strong>conflict</strong>, <strong>offline</strong>, <strong>authentication</strong>, <strong>dirty tree</strong>, <strong>busy</strong>, <strong>timeout</strong>, <strong>identity</strong>, <strong>markers</strong>). Hover it to read the full reason. If the backup commit happened before the failure, the message says so: it was made locally.</p><p>The button is greyed out, with the reason in its tooltip, when no remote is connected (&quot;No remote: connect one below.&quot;) or a git operation is already running.</p><h3 id="commit-your-changes-by-hand" tabindex="-1">Commit your changes by hand <a class="header-anchor" href="#commit-your-changes-by-hand" aria-label="Permalink to &quot;Commit your changes by hand&quot;">​</a></h3><p>In <strong>Changes</strong>:</p><ol><li>Click <strong>Show the list</strong> to read the files involved.</li><li>Write a <strong>Commit message</strong>.</li><li>Click <strong>Commit the changes</strong>, then <strong>Confirm</strong> at the question &quot;Commit N changes with this message?&quot;. <strong>Cancel</strong> drops it.</li></ol><p>The field is pre-filled by the <strong>Manual</strong> origin&#39;s template (by default &quot;vault backup: YYYY-MM-DD HH:mm:ss&quot;): you can edit it, and once you type in it Kessho no longer replaces it. The button stays greyed out while the message is empty. The message cannot exceed 1,000 characters. Your commit name and email must be filled in your profile (the circle with your initial, top right).</p><h3 id="pull-or-push" tabindex="-1">Pull or push <a class="header-anchor" href="#pull-or-push" aria-label="Permalink to &quot;Pull or push&quot;">​</a></h3><ul><li><strong>Pull</strong> fetches what is new on the remote and applies it. It is greyed out while changes are uncommitted: &quot;Uncommitted changes prevent pulling: commit them first.&quot;</li><li><strong>Push</strong> sends your commits. It is greyed out when there is nothing to push.</li><li><strong>Sync</strong> pulls, then pushes.</li></ul><p>Kessho never pulls on its own: the state line shows &quot;N to pull&quot;, and you decide.</p><h3 id="connect-a-remote" tabindex="-1">Connect a remote <a class="header-anchor" href="#connect-a-remote" aria-label="Permalink to &quot;Connect a remote&quot;">​</a></h3><p>In <strong>Remote</strong>, paste the repository&#39;s address into <strong>Remote URL (https or ssh)</strong> and click <strong>Connect</strong> (the button reads <strong>Change</strong> once a remote is connected). The accepted forms are <code>https://host/path</code>, <code>ssh://host/path</code> and <code>user@host:path</code>.</p><p>No credential is stored: Kessho uses your system&#39;s own. An address that carries one is refused.</p><h3 id="initialise-the-repository" tabindex="-1">Initialise the repository <a class="header-anchor" href="#initialise-the-repository" aria-label="Permalink to &quot;Initialise the repository&quot;">​</a></h3><p>If your memory is not a repository yet, click <strong>Initialise the repository</strong>. It creates no commit and connects no remote.</p><h3 id="let-your-agents-sync" tabindex="-1">Let your agents sync <a class="header-anchor" href="#let-your-agents-sync" aria-label="Permalink to &quot;Let your agents sync&quot;">​</a></h3><p>The <strong>Automation</strong> checkbox (&quot;Agents commit and sync automatically&quot;) is ticked by default. When it is ticked, each tool of your AI agents that writes to the memory commits only what it touched, then pushes. Your uncommitted changes never leave with it. Untick the box to take control back.</p><p>The first line of these commits&#39; message is set in <a href="#compose-your-commit-messages">Compose your commit messages</a>.</p><p>To ask an agent to sync, see <a href="/en/agent/synchroniser.html">Sync the memory</a>. The matching tools are described in the <a href="/en/reference/mcp/git.html">MCP reference</a>.</p><h3 id="compose-your-commit-messages" tabindex="-1">Compose your commit messages <a class="header-anchor" href="#compose-your-commit-messages" aria-label="Permalink to &quot;Compose your commit messages&quot;">​</a></h3><p>In <strong>Commit messages</strong> (Settings &gt; Sync, visible when the memory is a git repository), each commit origin composes its message from a <strong>template</strong>: one of the supplied templates, or your own. The template sets the first line of the message. As long as you do not touch it, nothing changes: each origin keeps its usual message.</p><h4 id="the-four-origins" tabindex="-1">The four origins <a class="header-anchor" href="#the-four-origins" aria-label="Permalink to &quot;The four origins&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Origin</th><th>What the template sets</th><th>Default template</th></tr></thead><tbody><tr><td><strong>One click</strong></td><td>The message of the commit made by the <strong>Sync the memory</strong> button.</td><td><strong>Timestamped</strong>: <code>vault backup: {date} {heure_s}</code>, that is &quot;vault backup: 2026-10-21 14:05:09&quot;.</td></tr><tr><td><strong>Automation</strong></td><td><strong>Only the first line</strong> of the commit that one of your AI agents&#39; tools makes after writing. The body, which lists the files, and the <code>Kessho-Outil</code>, <code>Kessho-Embarque</code> and <code>Kessho-Repris</code> lines always stay.</td><td><strong>Kessho · tool</strong>: <code>kessho({outil}): {objet} {demande}</code>, for example &quot;kessho(mem_note): Architecture&quot;.</td></tr><tr><td><strong>Manual</strong></td><td>The pre-filled content of the <strong>Commit message</strong> field; you can edit it before committing.</td><td><strong>Timestamped</strong></td></tr><tr><td><strong>AI agent</strong></td><td>The message of a commit the agent makes through <code>mem_git_commit</code>. The agent&#39;s message is always kept: the agent&#39;s template can only surround it (it must contain <code>{message}</code>, otherwise it is ignored with a warning), and an empty message is always refused.</td><td><strong>Agent&#39;s message</strong>: <code>{message}</code>, the message exactly as the agent wrote it.</td></tr></tbody></table><p>The message of a conflict resolution is never affected: Kessho composes it itself.</p><p>A subject composed by a template is cut at 72 characters (with &quot;…&quot;) for every template except <strong>Kessho · tool</strong> and <strong>Agent&#39;s message</strong>, which are never cut; the <strong>AI agent</strong> origin is never subject to it. When a subject is cut, Kessho reports it.</p><p>If the chosen template no longer renders, Kessho uses the origin&#39;s default template and says so: the <strong>Preview</strong> shows &quot;The saved template is missing or invalid: the default template is used.&quot; For the <strong>One click</strong> origin, the commit goes ahead with the default template and the status bar shows a non-blocking warning, &quot;default template used&quot;. The sync only stops before any commit if no usable message could be composed; the failure then appears in the status bar.</p><h4 id="choose-a-template" tabindex="-1">Choose a template <a class="header-anchor" href="#choose-a-template" aria-label="Permalink to &quot;Choose a template&quot;">​</a></h4><ol><li>On the origin&#39;s line, click the template&#39;s name: a menu opens, with <strong>Supplied templates</strong> and <strong>My templates</strong>.</li><li>Pick one: it is saved at once, and the line&#39;s <strong>Preview</strong> updates.</li><li>To go back to the origin&#39;s default template, click <strong>Restore default</strong> (the button only appears once you have changed it).</li></ol><h4 id="the-six-supplied-templates" tabindex="-1">The six supplied templates <a class="header-anchor" href="#the-six-supplied-templates" aria-label="Permalink to &quot;The six supplied templates&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Template</th><th>Example</th></tr></thead><tbody><tr><td><strong>Timestamped</strong></td><td><code>vault backup: {date} {heure_s}</code></td><td>vault backup: 2026-10-21 14:05:09</td></tr><tr><td><strong>Journal</strong></td><td><code>{date} {heure} · {utilisateur|—}</code></td><td>2026-10-21 14:05 · Ben</td></tr><tr><td><strong>Conventional Commits</strong></td><td><code>chore(vault): {action|mise à jour} {n_total|plusieurs} note(s)</code></td><td>chore(vault): modification 4 note(s)</td></tr><tr><td><strong>Agent trace</strong></td><td><code>[{origine}] {outil} — {objet}</code></td><td>[automatisme] mem_note — Architecture</td></tr><tr><td><strong>Kessho · tool</strong></td><td><code>kessho({outil}): {objet} {demande}</code></td><td>kessho(mem_note): Architecture (apply)</td></tr><tr><td><strong>Agent&#39;s message</strong></td><td><code>{message}</code></td><td>correction de la note</td></tr></tbody></table><p>No supplied template uses a sensitive variable (see the warning below).</p><h4 id="a-template-s-syntax" tabindex="-1">A template&#39;s syntax <a class="header-anchor" href="#a-template-s-syntax" aria-label="Permalink to &quot;A template&#39;s syntax&quot;">​</a></h4><ul><li><code>{variable}</code> is replaced by its value when the commit is made.</li><li><code>{variable|default}</code> gives fallback text when the variable is empty. The fallback text cannot contain a brace.</li><li><code>{{</code> writes an opening brace, <code>}}</code> a closing brace.</li><li>A template fits on <strong>a single line</strong> and is at most 500 characters; the resulting message can be neither empty nor longer than 1,000 characters.</li><li>An unknown variable, an unpaired brace or a control character is refused with a message that says what, and where when it is a position: a typo never reaches the history. The editor then lists the valid variables.</li><li>A variable with no value gives its fallback, otherwise nothing: a commit does not fail over a missing counter.</li></ul><h4 id="the-variables" tabindex="-1">The variables <a class="header-anchor" href="#the-variables" aria-label="Permalink to &quot;The variables&quot;">​</a></h4><p>They are grouped by family in the editor, where a click on a variable inserts it at the cursor. When a variable has no value for the origin you are previewing, the editor says so: it will stay empty unless you give a fallback.</p><table tabindex="0"><thead><tr><th>Family</th><th>Variable</th><th>What it gives</th><th>Example</th></tr></thead><tbody><tr><td>Time</td><td><code>{date}</code></td><td>Today&#39;s date</td><td>2026-10-21</td></tr><tr><td>Time</td><td><code>{heure}</code></td><td>Time, without seconds</td><td>14:05</td></tr><tr><td>Time</td><td><code>{heure_s}</code></td><td>Time, with seconds</td><td>14:05:09</td></tr><tr><td>Time</td><td><code>{iso}</code></td><td>Full date and time (ISO 8601), with the time zone</td><td>2026-10-21T14:05:09+02:00</td></tr><tr><td>Time</td><td><code>{semaine}</code></td><td>Week number</td><td>43</td></tr><tr><td>Time</td><td><code>{fuseau}</code></td><td>Local time offset</td><td>+02:00</td></tr><tr><td>Volume</td><td><code>{n_modifies}</code></td><td>Number of modified notes (not for automation)</td><td>3</td></tr><tr><td>Volume</td><td><code>{n_ajoutes}</code></td><td>Number of added notes (not for automation)</td><td>1</td></tr><tr><td>Volume</td><td><code>{n_supprimes}</code></td><td>Number of deleted notes (not for automation)</td><td>0</td></tr><tr><td>Volume</td><td><code>{n_total}</code></td><td>Total number of notes touched (not for automation)</td><td>4</td></tr><tr><td>Context</td><td><code>{utilisateur}</code></td><td>Your name, as signed in the Profile</td><td>Ben</td></tr><tr><td>Context</td><td><code>{appareil}</code> (sensitive)</td><td>Name of this computer</td><td>MacBook-de-Ben</td></tr><tr><td>Context</td><td><code>{memoire}</code></td><td>Name of the memory (its folder)</td><td>SecondBrain</td></tr><tr><td>Context</td><td><code>{branche}</code></td><td>Current git branch</td><td>main</td></tr><tr><td>Context</td><td><code>{version}</code></td><td>Kessho version</td><td>0.3.1</td></tr><tr><td>Origin</td><td><code>{origine}</code></td><td>Origin of the commit</td><td>un-clic</td></tr><tr><td>Origin</td><td><code>{outil}</code></td><td>Tool that wrote (automation only)</td><td>mem_note</td></tr><tr><td>Origin</td><td><code>{objet}</code></td><td>What was written, for example a note&#39;s title (automation only)</td><td>Architecture</td></tr><tr><td>Origin</td><td><code>{message}</code></td><td>Message typed in (only has a real value for the agent; the manual preview shows an example)</td><td>correction de la note</td></tr><tr><td>Origin</td><td><code>{demande}</code></td><td>Mode of the tool&#39;s request (automation only)</td><td>(apply)</td></tr><tr><td>Action</td><td><code>{action}</code></td><td>Kind of change: addition, modification, deletion (not for automation; empty when there is no change)</td><td>modification</td></tr><tr><td>Content</td><td><code>{zones}</code> (sensitive)</td><td>Memory zones touched</td><td>10-episodes, 20-knowledge</td></tr><tr><td>Content</td><td><code>{projets}</code> (sensitive)</td><td>Projects touched</td><td>kessho, atelier</td></tr><tr><td>Content</td><td><code>{fichiers}</code> (sensitive)</td><td>Notes touched (the first ones, then the rest as +N)</td><td>a.md, b.md +3</td></tr></tbody></table><p><code>{origine}</code> is <code>un-clic</code>, <code>automatisme</code>, <code>manuel</code> or <code>agent</code>.</p><h4 id="warning-what-the-sensitive-variables-write" tabindex="-1">Warning: what the sensitive variables write <a class="header-anchor" href="#warning-what-the-sensitive-variables-write" aria-label="Permalink to &quot;Warning: what the sensitive variables write&quot;">​</a></h4><p>The content variables (<code>{zones}</code>, <code>{projets}</code>, <code>{fichiers}</code>) and <code>{appareil}</code> reveal what your memory contains or the name of your computer. The composed message is written into the git history, then pushed to the remote repository you chose: once it is there, it stays. No supplied template contains them, and Kessho never puts them in a template you did not write. In the editor they are folded under <strong>Sensitive variables</strong>, and as soon as your template uses one, a privacy note names it.</p><h4 id="create-edit-delete-a-personal-template" tabindex="-1">Create, edit, delete a personal template <a class="header-anchor" href="#create-edit-delete-a-personal-template" aria-label="Permalink to &quot;Create, edit, delete a personal template&quot;">​</a></h4><ul><li><strong>New template</strong> (or <strong>New template…</strong> in an origin&#39;s menu) opens the editor. Give a <strong>Template name</strong> (1 to 40 characters) and write the <strong>Template</strong>. You can keep 20 at most.</li><li>The <strong>Preview</strong> updates live, with the same engine as the commit. Pick the previewed origin under <strong>Preview for origin</strong>: the preview renders like that origin&#39;s commit.</li><li>While the template is refused, <strong>Save template</strong> stays greyed out and the error message says why. A template created from an origin&#39;s line is chosen for that origin at once.</li><li><strong>Edit</strong> reopens a template from <strong>My templates</strong>. If you leave the editor with changes, Kessho asks &quot;Discard the changes to this template?&quot;.</li><li><strong>Delete template</strong> asks for confirmation and names the origins that use it: they go back to their default template.</li></ul><h3 id="understand-a-refusal" tabindex="-1">Understand a refusal <a class="header-anchor" href="#understand-a-refusal" aria-label="Permalink to &quot;Understand a refusal&quot;">​</a></h3><p>The messages say what to do. The most common ones:</p><ul><li><strong>Conflict</strong>: the pull is cancelled and nothing changed. The files involved are named: merge them by hand, commit, then sync.</li><li><strong>Push refused</strong>: the remote moved ahead. Pull first. Nothing is ever forced.</li><li><strong>Offline</strong>: the remote cannot be reached. Nothing changed, try again later.</li><li><strong>Authentication refused</strong>: Kessho uses your system&#39;s credentials. For GitHub over https, run &quot;gh auth login&quot;; otherwise switch the remote to SSH.</li><li><strong>Operation in progress</strong> or <strong>repository busy</strong>: another git process is working on the memory. Wait a moment.</li></ul><p>Under <strong>Warnings</strong>, Kessho also tells you when conflict markers have been committed in a file, when it resumed an interrupted operation, or when the Obsidian Git plugin is syncing the same memory (two automations get in each other&#39;s way: set its intervals to 0). Kessho never changes Obsidian&#39;s configuration.</p><h3 id="know-when-the-memory-changed" tabindex="-1">Know when the memory changed <a class="header-anchor" href="#know-when-the-memory-changed" aria-label="Permalink to &quot;Know when the memory changed&quot;">​</a></h3><p>The freshness indicator, top right, lights up when the memory changes, for example when an agent has just written. Click it to open its panel.</p>',55)),n(s,{name:"fraicheur",alt:"The freshness indicator, top right: an agent has just written in the Procedures zone, the indicator lights up and says what moved."}),e[3]||(e[3]=t("ul",null,[t("li",null,'The first line says since when: "Seen a second ago." With no change since opening: "No change since opening." If the reading fails: "The memory state could not be read."'),t("li",null,[t("strong",null,"Changes since the last reload"),o(` lists the zones that moved, with the number of changes: "Procedures 1". The number counts changes, not the zone's size: adding a note then removing it makes two.`)]),t("li",null,'When a note changed without any zone changing size, the panel says so: "A note changed, without any zone changing size."'),t("li",null,[t("strong",null,"Reload"),o(" refreshes what the screen shows and resets the count.")])],-1))])}const w=a(l,[["render",c]]);export{b as __pageData,w as default};
